'use strict';
const BASE='/adapters/asset-machine',API=BASE+'/api', $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let user=null,cases=[],current=null,tab='overview',view='projects',status={},media=null,recordTimer=null,audio=null,busyDepth=0;
const labels={instrument:'Bond, bank instrument or physical asset',wallet:'Crypto wallet',contract:'Smart contract',digital:'Digital asset',intake:'Intake',evidence_needed:'Evidence needed',ready_for_review:'Awaiting legal review',under_review:'Under legal review',review_complete:'Report released',declined:'Declined'};
const date=x=>x?new Date(x).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}):'—';
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,6500);}
async function work(label,fn){busyDepth++;$('#busy-text').textContent=label;$('#busy').hidden=false;try{return await fn();}catch(e){toast(e.message);throw e;}finally{if(--busyDepth<=0){busyDepth=0;$('#busy').hidden=true;}}}
async function api(path,opt={}){const headers={...(opt.body&&!(opt.body instanceof FormData)&&!opt.raw?{'Content-Type':'application/json'}:{}),...(opt.method&&opt.method!=='GET'?{'X-CSRF-Token':user?.csrf||''}:{}),...opt.headers};const response=await fetch(API+path,{...opt,headers,body:opt.body&&!(opt.body instanceof FormData)&&!opt.raw?JSON.stringify(opt.body):opt.body});if(!response.ok){const d=await response.json().catch(()=>({}));throw Error(d.error?.message||'This request could not finish.');}return opt.blob?response.blob():response.json();}
const post=(p,b={})=>api(p,{method:'POST',body:b});
function modal(html,kicker='PRIVATE WORKSPACE'){$('#modal-kicker').textContent=kicker;$('#modal-content').innerHTML=html;$('#modal').showModal();}
function closeModal(){$('#modal').close();}
function download(name,text,type='text/plain'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function safeHref(x){try{const u=new URL(x);return u.protocol==='https:'&&!u.username&&!u.password?u.href:'#';}catch{return '#';}}
function login(){if(['assetmachine.live','www.assetmachine.live'].includes(location.hostname)){location.href='https://swadebase.cloud'+BASE+'/#workspace';return;}modal(`<h2>Your private<br><em>workspace.</em></h2><p>Sign in with your confirmed SWADEBASE account. Access is limited to people added by the workspace owner.</p><a class="button primary" href="${BASE}/auth/google">Continue with Google ↗</a><p class="field-note">Uses your existing SWADEBASE identity.</p><form id="login-form"><label for="email">Email</label><input id="email" name="email" type="email" autocomplete="username" required><label for="password">Password</label><input id="password" name="password" type="password" autocomplete="current-password" required><p class="error-text" id="login-error"></p><div class="form-end"><button class="primary" type="submit">Sign in ↗</button></div></form><p class="fine">Founder? Your existing SWADEBASE owner session is recognized automatically. No private keys or wallet recovery phrases are needed.</p>`);$('#login-form').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));try{await work('Signing in securely…',()=>post('/login',b));closeModal();await initSession();location.hash='workspace';}catch(x){$('#login-error').textContent=x.message;}finally{$('#password').value='';}};}
async function initSession(){try{user=(await api('/session')).user;}catch{user=null;}$('#account').textContent=user?'Open workspace ↗':'Client sign in ↗';if(user){$('#identity').innerHTML=`<strong>${esc(user.role==='reviewer'?'Legal reviewer':user.role==='owner'?'Workspace owner':user.role==='admin'?'Workspace administrator':'Client')}</strong><br>${esc(user.email)}`;$('#review-nav').hidden=user.role!=='reviewer';$('#access-nav').hidden=!['owner','admin'].includes(user.role);try{status=await api('/status');}catch{status={};}}}
function begin(type='instrument'){if(!user){login();return;}newCase(type);}
function newCase(type='instrument'){modal(`<h2>Start with<br><em>what you have.</em></h2><p>Create a project, then add supporting evidence. Your description is recorded as your statement, not an independently verified finding.</p><form id="case-form"><p class="notice">${experience==='plain'?'Use your own words. You can add the technical details later.':'Record the holding and objective; unverified statements remain attributed claims.'}</p><label for="title">What would you like to call this project?</label><input id="title" name="title" maxlength="160" placeholder="A clear name for this holding" required><label for="asset_type">Asset type</label><select id="asset_type" name="asset_type">${['instrument','wallet','contract','digital'].map(t=>`<option value="${t}" ${type===t?'selected':''}>${labels[t]}</option>`).join('')}</select><label for="description">What do you have, and what would you like to do?</label><textarea id="description" name="description" rows="4" maxlength="12000" required></textarea><details class="advanced-fields" ${experience==='professional'?'open':''}><summary>${experience==='plain'?'Add details if you know them (optional)':'Instrument and network particulars'}</summary><div class="form-grid"><div><label for="issuer">Stated issuer / creator</label><input id="issuer" name="issuer" maxlength="300"></div><div><label for="face_amount">Claimed face amount / value</label><input id="face_amount" name="face_amount" maxlength="100"><p class="field-note">A claim, not a verified valuation.</p></div><div><label for="issue_date">Stated issue date</label><input id="issue_date" name="issue_date" maxlength="100"></div><div><label for="chain">Network, if applicable</label><select id="chain" name="chain"><option value="">Not applicable<option value="ethereum">Ethereum</option><option value="polygon">Polygon</option><option value="base">Base</option><option value="xrpl">XRP Ledger</option></select></div><div class="full"><label for="address">Public wallet / contract address</label><input id="address" name="address" maxlength="160" autocomplete="off"><p class="field-note">Never enter a private key or recovery phrase.</p></div></div></details><label for="goal">What would you like help with?</label><input id="goal" name="goal" placeholder="Legal review, sale feasibility, ownership questions…" maxlength="1000"><div class="form-end"><button class="primary">Create project ↗</button></div></form>`,'NEW PROJECT');$('#case-form').onsubmit=async e=>{e.preventDefault();try{const d=await work('Creating your project…',()=>post('/cases',Object.fromEntries(new FormData(e.target))));closeModal();location.hash='case/'+d.case.id;}catch{}};}
async function route(){const hash=location.hash.slice(1);window.AssetKnowledge?.cancel();$('#learning').classList.remove('kb-view');$('#learning').hidden=true;if(hash==='knowledge'||hash.startsWith('knowledge/')){window.scrollTo(0,0);await showKnowledge(hash);return;}if(hash==='learn'||hash.startsWith('learn/')){showLearning(hash.split('/')[1]||'');window.scrollTo(0,0);return;}if(!['workspace','access','review'].includes(hash)&&!hash.startsWith('case/')){showLanding();if(hash&&document.getElementById(hash))setTimeout(()=>document.getElementById(hash).scrollIntoView(),0);return;}if(!user){showLanding();login();return;}$('#landing').hidden=true;$('#workspace').hidden=false;$('#footer').hidden=true;$('.topbar nav').hidden=true;if(hash.startsWith('case/')){try{await loadCase(hash.slice(5));}catch(e){toast(e.message);location.hash='workspace';}return;}current=null;$('#assistant-toggle').hidden=true;$('#assistant').hidden=true;view=hash==='access'?'access':hash==='review'?'review':'projects';await dashboard();}
function showLanding(){$('#learning').hidden=true;$('#landing').hidden=false;$('#workspace').hidden=true;$('#footer').hidden=false;$('.topbar nav').hidden=false;$('#assistant-toggle').hidden=true;$('#assistant').hidden=true;}
async function dashboard(){document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('side-active',b.dataset.view===view));if(view==='access'){await accessView();return;}const d=await api('/cases');cases=d.cases;const legal=user.role==='reviewer';$('#work-content').innerHTML=`<div class="work-header"><div><p class="eyebrow">${legal?'DANNY BYERS / LEGAL REVIEW':'YOUR PRIVATE ASSET WORKSPACE'}</p><h2>${legal?'The review desk.':'What would you like to work on?'}</h2><p>${legal?'Evidence, analysis and your independent judgment.':'Open a project, add what you have, and follow the next step.'}</p></div>${!legal?'<button class="primary" id="new-case">New project ↗</button>':''}</div><div class="stats"><div class="stat"><strong>${cases.length}</strong><span>${legal?'Assigned matters':'Projects'}</span></div><div class="stat"><strong>${cases.filter(c=>['ready_for_review','under_review'].includes(c.status)).length}</strong><span>In review journey</span></div><div class="stat"><strong>${cases.filter(c=>c.status==='review_complete').length}</strong><span>Reports released</span></div></div><div class="notice journey-note"><strong>Not sure where to start?</strong> <a href="#learn">Read a short asset guide ↗</a> or <a href="#learn/desks">choose the right kind of professional ↗</a>.</div><input class="search" id="project-search" aria-label="Search projects" placeholder="Search your projects…"><div class="project-list" id="project-list"></div>${legal?'<div class="notice" style="margin-top:25px">Your working notes and drafts are private to your assigned reviewer role. Clients see only reports you approve and release.</div>':''}`;if($('#new-case'))$('#new-case').onclick=()=>newCase();$('#project-search').oninput=e=>renderCases(e.target.value);renderCases('');}
function renderCases(search){const list=cases.filter(c=>[c.title,c.asset_type,c.status].join(' ').toLowerCase().includes(search.toLowerCase()));$('#project-list').innerHTML=list.length?list.map(c=>`<button class="project-row" data-case="${c.id}"><div><span class="tiny">${esc(labels[c.asset_type])}</span><h3>${esc(c.title)}</h3><p>${c.evidence_count} document${c.evidence_count===1?'':'s'} · Updated ${date(c.updated_at)}</p></div><div><span class="pill ${c.status==='review_complete'?'green':'gold'}">${esc(labels[c.status])}</span><p style="margin-top:15px;text-align:right">Open project ↗</p></div></button>`).join(''):`<div class="empty"><h3>${search?'No matching projects.':user.role==='reviewer'?'A clear desk.':'Your next chapter starts here.'}</h3><p>${user.role==='reviewer'?'Assigned projects will appear here when submitted.':'Create your first project and bring the supporting evidence into one place.'}</p>${user.role!=='reviewer'?'<button class="primary" id="empty-create">Create a project ↗</button>':''}</div>`;document.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>location.hash='case/'+b.dataset.case);if($('#empty-create'))$('#empty-create').onclick=()=>newCase();}
async function loadCase(id){current=await api('/cases/'+id);renderCase();}
function renderCase(){const d=current,c=d.case;$('#assistant-toggle').hidden=false;$('#work-content').innerHTML=`<button class="crumb" id="back">← All projects</button><div class="case-header"><div><span class="tiny">${esc(labels[c.asset_type])}</span><h2>${esc(c.title)}</h2><span class="case-id">PROJECT ${esc(c.id.slice(0,8).toUpperCase())} · ${date(c.created_at)}</span></div><div class="row-actions"><span class="pill ${c.status==='review_complete'?'green':'gold'}">${esc(labels[c.status])}</span><button class="outline mini" id="case-chat">◉ Talk about this project</button></div></div><div class="tabs" role="tablist" aria-label="Project sections">${[['overview','Overview'],['evidence',experience==='plain'?'My documents':'Evidence'],['findings',experience==='plain'?'What we found':'Findings'],['legal','Legal review'],['contacts',experience==='plain'?'Next conversations':'Counterparty briefing'],['activity',experience==='plain'?'Project history':'Audit history']].map(([id,label])=>`<button role="tab" aria-selected="${tab===id}" data-tab="${id}" class="${tab===id?'active':''}">${label}</button>`).join('')}</div><div id="case-panel"></div>`;$('#back').onclick=()=>location.hash='workspace';$('#case-chat').onclick=openAssistant;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{if(tab==='legal'&&d.can_review&&hasUnsaved()&&!confirm('You have unsaved review edits. Leave this tab?'))return;tab=b.dataset.tab;renderCase();});renderPanel();}
const endpoint=action=>'/cases/'+current.case.id+(action?'/'+action:'');
function overview(){const c=current.case;return nextStepPanel()+`<div class="two-col"><div class="panel"><p class="eyebrow">THE OWNER’S STATEMENT</p><h3>What is being reviewed?</h3><p style="white-space:pre-wrap">${esc(c.description)}</p><dl class="details">${Object.entries(c.fields).filter(([,v])=>v).map(([k,v])=>`<dt>${esc({issuer:'Stated issuer',face_amount:'Claimed amount',issue_date:'Stated issue date',address:'Public address',chain:'Network',goal:'Desired next step'}[k]||k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl></div><div class="panel"><p class="eyebrow">NEXT STEPS</p><h3>Build a complete picture.</h3><p>${current.evidence.length} supporting document${current.evidence.length===1?'':'s'} · ${current.findings.length} screening finding${current.findings.length===1?'':'s'}</p><div class="actions"><button class="outline mini" data-go="evidence">Add / review evidence ↗</button><button class="outline mini" id="screen">Run screening ↗</button></div><div class="notice" style="margin-top:20px">Automated screening identifies observations and questions. It does not authenticate an instrument, establish legal title or certify an investment.</div>${user.role!=='reviewer'?'<button class="primary mini" id="submit-review">Submit to Danny’s review queue ↗</button>':''}<p class="fine">$500 per project. Active legal review requires engagement acceptance and a recorded payment or an owner-approved payment exemption. Submission alone does not create a legal opinion.</p>${c.asset_type==='digital'?'<button class="outline mini" id="manifest">Download preparation record ↓</button><p class="fine">Metadata only. No asset is minted; Pinhub issuance awaits connection.</p>':''}</div></div>${current.reports.length?`<div class="panel"><p class="eyebrow">APPROVED & RELEASED</p><h3>Your legal report is available.</h3><button class="primary mini" data-go="legal">Read your report ↗</button></div>`:''}`;}
function evidencePanel(){return`<div class="panel"><p class="eyebrow">ORIGINALS & SOURCE MATERIAL</p><h3>The evidence room.</h3><p class="muted">PDF, PNG, JPEG and text · Up to 10 MB per file · Maximum 30 documents per project.</p>${user.role!=='reviewer'?'<label for="upload">Upload supporting documents</label><input class="file-input" id="upload" type="file" accept=".pdf,.png,.jpg,.jpeg,.txt" multiple><p class="field-note">For instruments, include front and back. Originals are encrypted before durable storage. OCR can make mistakes; confirm the extracted text.</p>':''}${current.evidence.length?current.evidence.map(e=>`<div class="doc-row"><div><h4>${esc(e.name)}</h4><p>${(e.bytes/1024).toFixed(0)} KB · ${esc(e.extraction_status.replaceAll('_',' '))}</p><p>SHA-256 ${esc(e.sha256.slice(0,24))}…</p></div><div class="row-actions"><button class="outline mini" data-text="${e.id}">Inspect text</button><button class="outline mini" data-download="${e.id}">Original ↓</button></div></div>`).join(''):'<div class="notice">No documents have been uploaded yet. Entered project details remain owner-supplied claims.</div>'}</div>`;}
function findingsPanel(){return`<div class="panel"><div class="work-header"><div><p class="eyebrow">OBSERVATIONS, CONCERNS & GAPS</p><h3>What the evidence says.</h3></div><button class="outline mini" id="screen">Run screening ↗</button></div><div class="notice">Each finding states its scope. These are not certificates of authenticity. Screening uses available text or a supported public ledger lookup.</div>${current.findings.length?current.findings.map(f=>`<article class="finding"><span class="pill ${f.kind==='concern'?'red':f.kind==='observation'?'green':'gold'}">${esc(f.kind)}</span><h4>${esc(f.title)}</h4><p>${esc(f.body)}</p><p><strong>Scope:</strong> ${esc(f.scope)}</p>${f.source_url?`<a class="source" href="${esc(safeHref(f.source_url))}" target="_blank" rel="noopener noreferrer">Source ↗</a>`:''}<p class="fine">Recorded ${date(f.created_at)}</p></article>`).join(''):'<p class="muted">Run screening after adding the available evidence.</p>'}</div>`;}
function legalPanel(){const c=current.case,r=current.review;return`<div class="notice">Independent legal review · Danny Byers · $500 per project. ${c.engagement_accepted?'Engagement accepted.':'Engagement not yet accepted.'} Payment: ${c.payment_exempt?'exempt - $0 required':c.payment_status==='recorded'?'external payment recorded':'not recorded'}.</div>${current.can_manage&&!c.payment_exempt?`<div class="panel"><h3>Review administration</h3><p>Record the receipt only after confirming the $500 review payment through the agreed external process. Online checkout is not enabled.</p><button class="outline mini" id="payment">Record confirmed payment</button><p class="fine">Danny’s working notes and unreleased drafts are restricted to his assigned reviewer role.</p></div>`:''}${current.can_review?`<div class="panel"><div class="work-header"><div><p class="eyebrow">DANNY’S PRIVATE REVIEW AREA</p><h3>Your analysis. Your judgment.</h3></div>${!c.engagement_accepted?'<button class="outline mini" id="engage">Accept engagement ↗</button>':'<span class="pill green">Engagement accepted</span>'}</div><label for="private-notes">Private working notes</label><textarea id="private-notes" class="notes-editor" maxlength="30000">${esc(r.notes)}</textarea><button class="outline mini" id="dictate-notes">● Dictate notes</button><label for="draft">Review memorandum / client report draft</label><textarea id="draft" class="draft-editor" maxlength="50000">${esc(r.draft)}</textarea><div class="review-bar"><button class="outline mini" id="draft-ai">Prepare AI draft ↗</button><button class="outline mini" id="dictate-draft">● Dictate into draft</button><button class="primary mini" id="save-review">Save version</button></div><p class="fine">Saved version ${r.version}${r.approved_version===r.version&&r.version?' · This version is approved':''}. AI assistance does not approve or release your report.</p><div class="review-bar"><button class="outline mini" id="approve">Approve saved version</button><button class="primary mini" id="release">Release approved report to client ↗</button></div><p class="fine">Approval applies to the exact saved version. Editing invalidates approval. Release makes the report available in the client portal; it sends no external email.</p></div>`:!current.reports.length?'<div class="panel"><h3>Awaiting independent review.</h3><p class="muted">The assigned attorney’s approved report will appear here after release. Internal notes and working drafts are private.</p></div>':''}${current.reports.map((r,i)=>`<div class="panel"><div class="work-header"><div><p class="eyebrow">RELEASED REPORT / VERSION ${r.review_version}</p><h3>${i===0?'Latest attorney report':'Earlier released version'}</h3><p>Released ${date(r.created_at)}</p></div><button class="outline mini" data-report="${r.id}">Download ↓</button></div><div class="report-text">${esc(r.body)}</div><p class="fine">SHA-256 ${esc(r.sha256)}<br>Legal review scope is defined by the report. This is not an issuer authentication or investment guarantee.</p><button class="outline mini" data-read-report="${r.id}">Listen to report excerpt ▷</button></div>`).join('')}`;}
function contactsPanel(){return`<div class="notice">Prepare the conversation before making an introduction. Contact details and source links entered here still require independent checks. Seed LEAKER discovery and external sending are not connected.</div><div class="panel"><div class="work-header"><div><p class="eyebrow">PROSPECT & CONTACT INTELLIGENCE</p><h3>The right conversation.</h3></div>${user.role!=='reviewer'?'<button class="primary mini" id="add-contact">Add a prospect ↗</button>':''}</div><p class="muted">A briefing records who the person is, why the opportunity may fit, what to say and which evidence is ready to share.</p>${current.contacts.length?current.contacts.map(c=>`<div class="finding"><span class="pill gold">Draft · Not sent</span><h4>${esc(c.name)}${c.firm?' / '+esc(c.firm):''}</h4><p>${esc(c.role)}${c.email?' · '+esc(c.email):''}</p><a class="source" href="${esc(safeHref(c.source_url))}" target="_blank" rel="noopener noreferrer">Supplied contact source ↗</a><p><strong>Additional diligence notes:</strong> ${esc(c.diligence||'Not yet supplied.')}</p><details><summary>Read contact briefing & suggested opening</summary><pre class="extract-text">${esc(c.brief)}</pre></details><button class="outline mini" data-brief="${c.id}">Download briefing ↓</button></div>`).join(''):'<p class="muted">No prospects recorded yet.</p>'}</div><div class="panel"><h3>Evidence before assertions.</h3><p>Any verification claim must identify the verifier, date, precise scope and supporting record. Private legal notes and reports are not automatically included in prospect briefings.</p><p class="fine">The proposed 2.1% success fee is inactive pending a separate legally permitted agreement. No outreach or transaction is initiated by this workspace.</p></div>`;}
function renderPanel(){const panel=$('#case-panel');panel.dataset.helpSection=tab;panel.innerHTML=tab==='overview'?overview():tab==='evidence'?evidencePanel():tab==='findings'?findingsPanel():tab==='legal'?legalPanel():tab==='contacts'?contactsPanel():`<div class="panel"><p class="eyebrow">PROJECT HISTORY</p><h3>A record of the work.</h3>${current.events.map(e=>`<div class="audit-row"><span>${esc(e.action.replaceAll('_',' '))}</span><time>${date(e.created_at)}</time></div>`).join('')}</div>`;if($('#action-report'))$('#action-report').onclick=()=>download('asset-action-summary.txt',actionReport());document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{tab=b.dataset.go;renderCase();});if($('#screen'))$('#screen').onclick=async()=>{try{await work('Examining the available evidence…',()=>post(endpoint('screen')));tab='findings';await loadCase(current.case.id);toast('Screening findings recorded. Independent review is still required.');}catch{}};if($('#submit-review'))$('#submit-review').onclick=async()=>{try{await work('Adding this project to the review queue…',()=>post(endpoint('submit')));await loadCase(current.case.id);toast('Project queued. Engagement and payment still need confirmation.');}catch{}};if($('#manifest'))$('#manifest').onclick=async()=>{try{download('asset-preparation-record.json',JSON.stringify(await api(endpoint('manifest')),null,2),'application/json');}catch(e){toast(e.message);}};if($('#upload'))$('#upload').onchange=upload;document.querySelectorAll('[data-text]').forEach(b=>b.onclick=()=>inspectText(b.dataset.text));document.querySelectorAll('[data-download]').forEach(b=>b.onclick=async()=>{try{const e=current.evidence.find(e=>e.id===b.dataset.download);await work('Retrieving and checking the original…',async()=>{const blob=await api(endpoint('evidence/'+e.id),{blob:true}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=e.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});}catch{}});if($('#payment'))$('#payment').onclick=payment;if($('#engage'))$('#engage').onclick=engage;if($('#save-review'))$('#save-review').onclick=saveReview;if($('#draft-ai'))$('#draft-ai').onclick=draftAI;if($('#dictate-notes'))$('#dictate-notes').onclick=()=>recordInto($('#private-notes'));if($('#dictate-draft'))$('#dictate-draft').onclick=()=>recordInto($('#draft'));if($('#approve'))$('#approve').onclick=()=>approveRelease('approve');if($('#release'))$('#release').onclick=()=>approveRelease('release');document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>{const r=current.reports.find(r=>r.id===b.dataset.report);download('legal-review-v'+r.review_version+'.txt',r.body);});document.querySelectorAll('[data-read-report]').forEach(b=>b.onclick=()=>speak(current.reports.find(r=>r.id===b.dataset.readReport).body));if($('#add-contact'))$('#add-contact').onclick=contactForm;document.querySelectorAll('[data-brief]').forEach(b=>b.onclick=()=>download('contact-briefing.txt',current.contacts.find(c=>c.id===b.dataset.brief).brief));}
async function upload(e){const files=[...e.target.files];for(const file of files){if(file.size>10000000){toast(file.name+' exceeds 10 MB.');continue;}try{await work('Encrypting, storing and reading '+file.name+'…',()=>api(endpoint('evidence'),{method:'POST',raw:true,body:file,headers:{'Content-Type':'application/octet-stream','X-File-Name':encodeURIComponent(file.name)}}));}catch{break;}}await loadCase(current.case.id);}
function inspectText(id){const e=current.evidence.find(e=>e.id===id);modal(`<h2>Inspect the<br><em>extracted text.</em></h2><p>${esc(e.name)} · ${esc(e.extraction_status.replaceAll('_',' '))}</p><p>Correct OCR mistakes here. This changes the working transcription; the original document remains intact.</p><label for="extracted">Working transcription</label><textarea id="extracted" rows="16" maxlength="100000">${esc(e.extracted_text)}</textarea><div class="form-end"><button class="primary" id="save-text">Save corrected text</button></div>`,'EVIDENCE INSPECTION');$('#save-text').onclick=async()=>{try{await work('Saving the corrected transcription…',()=>post(endpoint('evidence/'+id+'/text'),{text:$('#extracted').value}));closeModal();await loadCase(current.case.id);}catch{}};}
function payment(){modal('<h2>Record a confirmed<br><em>review payment.</em></h2><p>This records an external payment receipt. It does not charge a card or transfer money.</p><form id="payment-form"><label for="reference">External receipt / transaction reference</label><input name="reference" id="reference" required maxlength="300"><label class="check"><input type="checkbox" name="confirmed" required><span>I have independently confirmed receipt of the $500 review payment.</span></label><div class="form-end"><button class="primary">Record payment</button></div></form>','REVIEW ADMINISTRATION');$('#payment-form').onsubmit=async e=>{e.preventDefault();try{await work('Recording the payment reference…',()=>post(endpoint('payment'),{reference:$('#reference').value,confirm:true}));closeModal();await loadCase(current.case.id);}catch{}};}
function engage(){modal('<h2>Accept this<br><em>engagement.</em></h2><p>Confirm the review scope and professional checks before active review.</p><form id="engagement-form"><label class="check"><input type="checkbox" name="accept" required><span>I accept this matter under the agreed $500 project review scope.</span></label><label class="check"><input type="checkbox" name="conflicts_checked" required><span>I have completed the applicable conflict check.</span></label><label class="check"><input type="checkbox" name="jurisdiction_checked" required><span>I have confirmed jurisdiction and my ability to undertake this review.</span></label><div class="form-end"><button class="primary">Accept engagement</button></div></form>','ASSIGNED ATTORNEY ONLY');$('#engagement-form').onsubmit=async e=>{e.preventDefault();try{await work('Recording engagement acceptance…',()=>post(endpoint('engagement'),{accept:true,conflicts_checked:true,jurisdiction_checked:true}));closeModal();await loadCase(current.case.id);}catch{}};}
function hasUnsaved(){return current?.can_review&&$('#draft')&&($('#draft').value!==current.review.draft||$('#private-notes').value!==current.review.notes);}
async function saveReview(){try{await work('Saving a new review version…',()=>post(endpoint('review'),{draft:$('#draft').value,notes:$('#private-notes').value,version:current.review.version}));await loadCase(current.case.id);toast('Version saved. Approval is required before release.');}catch{}}
async function draftAI(){if(hasUnsaved()&&!confirm('AI will prepare a new draft. Save or copy your current edits first. Continue?'))return;const instructions=prompt('Optional instructions for the draft (do not include unsupported conclusions):','Prepare a scoped review memorandum and list missing evidence.');if(instructions===null)return;try{const d=await work('Preparing an evidence-grounded draft with native AI…',()=>post(endpoint('draft'),{instructions}));$('#draft').value=d.draft;toast('Draft prepared. Review, edit and save before approval.');}catch{}}
async function approveRelease(action){if(hasUnsaved()){toast('Save your edits before approval or release.');return;}if(!confirm(action==='approve'?'Approve this exact saved version as your reviewed report?':'Release this approved version to the client portal? No email will be sent.'))return;try{await work(action==='approve'?'Recording your approval…':'Releasing the approved report…',()=>post(endpoint(action),{version:current.review.version,confirm:true}));await loadCase(current.case.id);toast(action==='approve'?'Saved version approved.':'Report released to the authenticated client portal.');}catch{}}
function contactForm(){modal(`<h2>Prepare the<br><em>introduction.</em></h2><p>Add a prospect from a public, attributable source. This saves a briefing and does not send a message.</p><form id="contact-form"><div class="form-grid">${[['name','Contact name'],['firm','Firm / organization'],['email','Professional email'],['role','Role / decision authority']].map(([name,label])=>`<div><label for="contact-${name}">${label}</label><input id="contact-${name}" name="${name}" ${name==='name'?'required':''} maxlength="${name==='email'?254:180}" ${name==='email'?'type="email"':''}></div>`).join('')}</div><label for="source_url">Public HTTPS source</label><input type="url" id="source_url" name="source_url" required placeholder="https://…"><label for="interest">Why this may fit their documented interests</label><textarea id="interest" name="interest" rows="3" maxlength="1500"></textarea><label for="diligence">Counterparty checks / unresolved questions</label><textarea id="diligence" name="diligence" rows="3" maxlength="2000"></textarea><div class="form-end"><button class="primary">Prepare contact briefing ↗</button></div></form>`,'CONTACT INTELLIGENCE');$('#contact-form').onsubmit=async e=>{e.preventDefault();try{await work('Preparing the contact briefing…',()=>post(endpoint('contacts'),Object.fromEntries(new FormData(e.target))));closeModal();await loadCase(current.case.id);}catch{}};}

async function accessView(){
 if(!['owner','admin'].includes(user.role)){location.hash='workspace';return;}
 const d=await api('/members'),owner=user.role==='owner',invite=owner||user.can_invite;
 $('#work-content').innerHTML=`<div class="work-header"><div><p class="eyebrow">WORKSPACE ADMINISTRATION</p><h2>Access & connections.</h2><p>Manage the access you have been authorized to grant.</p></div>${invite?'<button class="primary" id="add-member">'+(owner?'Add workspace access':'Invite a client')+' ↗</button>':''}</div><div class="panel"><h3>Your permissions</h3><p>Project administration and available evidence/report downloads. ${user.payment_exempt?'Your site payments are exempt.':''} ${invite?'You may invite clients.':''} User deletion is unavailable. Only the owner can change privileged roles or payment exemptions.</p></div><div class="panel"><h3>People & roles</h3><p class="fine">Sign in with the approved Google/SWADEBASE email. Invitations grant client access; share the sign-in link after saving. No email is sent automatically.</p>${d.members.map(m=>`<div class="member-row"><div>${esc(m.email)}<br><span class="fine">${!m.active?'Access suspended':m.linked?'Linked identity':'Awaiting confirmed sign-in'}${m.payment_exempt?' · Payment exempt':''}${m.can_invite?' · May invite clients':''}</span></div><span class="pill">${esc(m.role)}</span>${owner&&m.active?`<button class="outline mini" data-suspend="${esc(m.email)}" data-role="${esc(m.role)}">Suspend access</button>`:''}</div>`).join('')}</div><div class="connection-grid">${[['Encrypted evidence storage',status.storage?'Connected':'Unavailable'],['Native voice',status.voice?'Connected':'Unavailable'],['Document extraction','Available'],['Native case assistant','Available'],['Seed LEAKER discovery','Connection pending'],['Pinhub issuance','Connection pending'],['Online checkout','Not enabled'],['2.1% success fee','Inactive']].map(([name,state])=>`<div class="connection"><h4>${name}</h4><span class="pill">${state}</span></div>`).join('')}</div>`;
 document.querySelectorAll('[data-suspend]').forEach(b=>b.onclick=async()=>{if(!confirm('Suspend workspace access for '+b.dataset.suspend+'?'))return;try{await work('Suspending workspace access…',()=>post('/members',{email:b.dataset.suspend,role:b.dataset.role,active:false}));await accessView();}catch{}});
 if(!$('#add-member'))return;
 $('#add-member').onclick=()=>{
  modal(`<h2>${owner?'Grant workspace':'Invite a client'}<br><em>access.</em></h2><form id="member-form"><label for="member-email">Approved account email</label><input id="member-email" name="email" type="email" required><label for="member-role">Role</label><select id="member-role" name="role"><option value="client">Client - own projects and released reports</option>${owner?'<option value="reviewer">Reviewer - assigned legal work</option><option value="admin">Administrator - project management</option>':''}</select>${owner?'<label class="check"><input type="checkbox" name="can_invite"><span>May invite new clients (administrator role only)</span></label><label class="check"><input type="checkbox" name="payment_exempt"><span>Exempt from site payments</span></label>':''}<p class="fine">No user deletion. Inviting clients does not grant authority to change other administrators, suspend users, or waive their payments.</p><div class="form-end"><button class="primary">${owner?'Save access':'Create client invitation'} ↗</button></div></form>`);
  $('#member-form').onsubmit=async e=>{e.preventDefault();const f=e.target,b={email:f.elements.email.value,role:f.elements.role.value};if(owner){b.can_invite=f.elements.can_invite.checked;b.payment_exempt=f.elements.payment_exempt.checked;}
   try{const out=await work('Saving approved access…',()=>post('/members',b));await accessView();modal(`<h2>Access is ready.</h2><p>Ask ${esc(b.email)} to open this link and choose the same approved Google account.</p><label for="invite-link">Sign-in link to share</label><input id="invite-link" readonly value="${esc(out.invite_url)}"><button class="primary" id="copy-invite">Copy invitation link</button><p class="fine">The recipient must authenticate with the approved email. This link alone grants no access. No email has been sent automatically.</p>`);$('#copy-invite').onclick=async()=>{try{await navigator.clipboard.writeText(out.invite_url);toast('Invitation link copied.');}catch{$('#invite-link').select();toast('Select and copy the sign-in link.');}};
   }catch{}
  };
 };
}

function renderMessages(){$('#messages').innerHTML=current.messages.length?current.messages.map(m=>`<div class="message ${m.role}"><span class="tiny">${m.role==='user'?'YOU':'PROJECT ASSISTANT'}</span><p>${esc(m.body)}</p>${m.role==='assistant'&&Array.isArray(m.knowledge_sources)&&m.knowledge_sources.length?`<div class="message-knowledge"><span class="tiny">PUBLIC EDUCATIONAL REFERENCES</span><ul>${m.knowledge_sources.slice(0,6).filter(x=>x&&safeHref(x.url)!=='#').map(x=>`<li><a href="${esc(safeHref(x.url))}" target="_blank" rel="noopener noreferrer">${esc(x.label)} · ${esc(x.name)} ↗</a></li>`).join('')}</ul></div>`:''}${m.role==='assistant'?'<button class="outline mini" data-speak="'+esc(m.body.slice(0,2500))+'">Listen ▷</button>':''}</div>`).join(''):'<div class="notice">Ask about the evidence, missing information or next steps. Your conversation is scoped to this project and your access.</div>';document.querySelectorAll('[data-speak]').forEach(b=>b.onclick=()=>speak(b.dataset.speak));$('#messages').scrollTop=$('#messages').scrollHeight;}
function openAssistant(){if(!current)return;$('#assistant').hidden=false;$('#assistant-toggle').hidden=true;renderMessages();$('#chat-input').focus();}
async function speak(text){try{await work('Preparing native speech…',async()=>{if(audio){audio.pause();URL.revokeObjectURL(audio.src);}const blob=await api(endpoint('speak'),{method:'POST',body:{text:text.slice(0,2500)},blob:true});audio=new Audio(URL.createObjectURL(blob));audio.onended=()=>URL.revokeObjectURL(audio.src);await audio.play();});}catch{}}
async function recordInto(target){if(media&&media.state==='recording'){media.stop();return;}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('Recording is unavailable in this browser. You can type instead.');return;}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});const type=['audio/webm;codecs=opus','audio/mp4','audio/webm'].find(t=>MediaRecorder.isTypeSupported(t));media=new MediaRecorder(stream,type?{mimeType:type}:undefined);const chunks=[];media.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};media.onstop=async()=>{clearTimeout(recordTimer);stream.getTracks().forEach(t=>t.stop());$('#record').classList.remove('recording');$('#record').textContent='● Speak';$('#voice-status').textContent='';try{await work('Transcribing your recording…',async()=>{const form=new FormData();form.append('file',new Blob(chunks,{type:media.mimeType}),'voice');const d=await api(endpoint('transcribe'),{method:'POST',body:form});target.value+=(target.value?'\n':'')+d.text;target.focus();});}catch{}};media.start();$('#voice-status').textContent='Recording · up to 30 seconds. Click Speak again to stop.';$('#record').textContent='■ Stop recording';$('#record').classList.add('recording');recordTimer=setTimeout(()=>{if(media.state==='recording')media.stop();},29000);toast('Recording started. Click the microphone again to stop.');}catch{toast('Microphone access was not available. Check browser permission or type instead.');}}
// Public educational content only. Never populate share cards from private project state.
let experience='plain';
try{experience=localStorage.getItem('am-experience')==='professional'?'professional':'plain';}catch{}
const guides={
 bonds:{name:'Bonds and financial certificates',question:'What kind of bond do I have?',plain:'A bond records a promise to pay under specified terms. Start by identifying the issuer, the type of bond and whether an obligation remains outstanding. A printed amount is not the same as today’s value.',professional:'Classify the debt instrument, identify the obligor and distinguish the stated denomination from outstanding principal, redemption entitlement and supported market or collectible value.',checks:['Exact issuer name, country, instrument type and identifier, if present.','Issue date, maturity, coupon, amendments and cancellation markings.','Evidence of ownership and the institution that can confirm the position.'],steps:['Record the wording and photograph both sides.','Compare the instrument with the relevant issuer/reference records.','Ask the issuer, successor, transfer agent or custodian what remains payable and what evidence they require.'],terms:{Issuer:'The entity responsible for the obligation.',Maturity:'The contractual date principal becomes due, subject to the terms.',CUSIP:'An identifier used for securities; a matching number alone does not establish ownership.'},sources:[['Treasury securities information','https://home.treasury.gov/services/bonds-and-securities'],['FINRA fixed-income records','https://www.finra.org/finra-data/fixed-income']],type:'instrument'},
 sblc:{name:'SBLCs and bank guarantees',question:'I have—or need—a standby letter of credit.',plain:'An SBLC is a bank undertaking to pay a beneficiary when a demand meets its terms. It is not a promise that any holder can turn its face amount into cash. Start with the business purpose and the banks involved.',professional:'Review the undertaking’s issuer, applicant, beneficiary, operative terms, expiry, presentation requirements, applicable rules and amendments. Distinguish issuance/advising evidence from an uploaded purported SWIFT message.',checks:['Issuing/advising bank, applicant, beneficiary and undertaking reference.','Amount, currency, expiry, drawing conditions and all amendments.','Authority to request information and an independently established institutional confirmation channel.'],steps:['If applying, explain the underlying obligation to your bank’s trade-finance team.','Ask the bank which application, credit, collateral and fee requirements apply to your case.','If holding a document, obtain authorized institutional confirmation before relying on it.'],terms:{Applicant:'The customer asking the bank to issue the undertaking.',Beneficiary:'The party entitled to present a demand under the undertaking.',MT760:'A SWIFT message type used for guarantees/SBLCs; a copy is not independent evidence of transmission.'},sources:[['SWIFT Category 7 reference','https://www2.swift.com/knowledgecentre/rest/v1/publications/us7m_20230720/2.0/us7m_20230720.pdf'],['FBI warning on fictitious SBLCs','https://www.ic3.gov/PSA/2019/PSA190318']],type:'instrument'},
 inherited:{name:'Inherited bonds and documents',question:'A family member left me a bond. Where do I start?',plain:'First identify the exact asset. Savings bonds, outstanding securities and collectible certificates follow different paths. Inheriting the paper does not by itself establish who can redeem or transfer the asset.',professional:'Identify the security and registration, establish estate or beneficiary authority, and investigate the current issuer/successor and obligation status. Separate transferable or redeemable rights from scripophily value.',checks:['Names and registration on the document, series, dates and serial/identifier.','Any named co-owner or beneficiary and evidence of estate authority.','Issuer/successor status and whether a redemption or transfer process applies.'],steps:['Keep originals safe; start with copies for preliminary research.','Use the issuer’s official deceased-owner or transfer instructions.','Ask an estate professional or the relevant institution which authority documents are needed.'],terms:{Beneficiary:'A named recipient whose rights depend on the asset’s registration and applicable rules.',Scripophily:'Collecting historical stock and bond certificates.',Redemption:'Payment under the instrument’s actual terms and official process.'},sources:[['TreasuryDirect deceased-owner guidance','https://www.treasurydirect.gov/savings-bonds/manage-bonds/death-of-owner/'],['Treasury historical-bond warning','https://oig.treasury.gov/Scams/Historical-Bond-Fraud']],type:'instrument'},
 physical:{name:'Gold, gemstones and minerals',question:'What evidence matters for a physical asset?',plain:'Start with what the object or material is, where it is, who owns it and what independent testing supports the description. A photograph, stamped number or report cannot answer every question about the physical item.',professional:'Document identification, quantity/weight, fineness or grade, assay or laboratory evidence, provenance, chain of custody, title and location. Distinguish report-record matching from physical authentication and valuation.',checks:['Photographs, markings, measured quantity and current physical location.','Refiner, assay or gem laboratory report and its scope/date.','Ownership, custody and any transfer or shipment restrictions requiring specialist review.'],steps:['Identify the relevant specialist: assay/refinery for metals, gem laboratory for stones, qualified laboratory for mineral samples.','Check report details using the issuing organization’s official service when available.','Arrange an appropriate physical inspection before relying on a sale or valuation claim.'],terms:{Assay:'Testing the composition or purity of a material.',Fineness:'The proportion of precious metal in the material.',Provenance:'The documented history and origin of an item.'},sources:[['LBMA gold and silver standards','https://www.lbma.org.uk/publications/the-otc-guide/london-good-delivery-gold-and-silver'],['GIA report-record checking','https://www.gia.edu/gia-website/report-check-landing'],['USGS mineral information','https://www.usgs.gov/centers/national-minerals-information-center/mineral-commodity-summaries']],type:'instrument'},
 unknown:{name:'Unfamiliar names and unidentified items',question:'I do not know what this is.',plain:'That is a valid starting point. Names such as “golden dragon,” “golden drum” or “golden gun” need context. We should not assume they identify a recognized financial instrument, a particular material or an item with redeemable value.',professional:'Treat informal labels as unclassified claims. Establish the object/document, issuer or maker, provenance and relevant jurisdiction before assigning an instrument class or economic interpretation.',checks:['Exact wording, language, photographs, markings and dimensions.','Who supplied the description and what evidence supports it.','Whether this is a document, a commodity, a collectible or another physical object.'],steps:['Describe only what you can observe, separately from what someone told you.','Open a private project to organize the evidence.','Choose the appropriate qualified specialist after initial classification; actual firearms require an appropriate specialist route.'],terms:{Claim:'A statement awaiting supporting evidence.',Classification:'Identifying which category an item belongs to.',Authentication:'An assessment with a named source and explicit scope; never established just by an informal label.'},sources:[['Treasury examples of phony securities','https://oig.treasury.gov/Scams/Examples-of-Known-Phony-Securities']],type:'instrument'},
 desks:{name:'Find the right desk or professional',question:'Which kind of desk should I contact?',plain:'“Trade desk” can mean very different things. A securities desk, a bank’s trade-finance department and a bullion desk handle different needs. Start with your asset and goal, then check the organization’s stated services and eligibility.',professional:'Route by instrument, transaction objective, jurisdiction and counterparty mandate. Distinguish securities execution/distribution from documentary trade finance and physical commodity dealing; institutional acceptance remains case-specific.',checks:['Does the organization publicly document the service you need?','Which customers, jurisdictions, instruments and minimum sizes does it accept?','Are the representative, mandate and official contact channel independently established?'],steps:['For SBLCs/guarantees, ask for the bank’s trade-finance or guarantees team.','For securities, identify an appropriate broker/dealer, transfer agent or custodian according to the objective.','For metals, choose a relevant bullion dealer/refiner and inspection/custody specialist.'],terms:{'Securities desk':'A team handling supported securities transactions for eligible clients.','Trade finance':'Banking services related to commercial trade obligations and documents.','Bullion desk':'A team dealing in precious metals under its own terms and eligibility criteria.'},sources:[['FINRA BrokerCheck','https://brokercheck.finra.org/'],['Treasury warning on prime-bank trading schemes','https://oig.treasury.gov/Scams/Prime-Bank-Investment-Fraud'],['LBMA market standards','https://www.lbma.org.uk/publications/the-otc-guide/london-good-delivery-gold-and-silver']],type:'instrument'},
 digital:{name:'Wallets, contracts and tokenization',question:'Can this asset become a digital asset?',plain:'A token is a digital record. It needs a clear explanation of the rights it represents. Recording a claim on a blockchain does not make the underlying asset genuine, valuable or acceptable to a lender.',professional:'Separate ledger observations, control evidence, legal title, underlying custody, token-holder rights, issuance permissions and transfer restrictions. Oracle outputs are source-dependent attestations, not independent asset authentication.',checks:['Network, public wallet/contract address and claimed rights.','Underlying asset evidence and the custodian or responsible issuer.','Legal terms, permitted transfers and the exact scope/freshness of any attestation.'],steps:['Organize the underlying rights and evidence first.','Review public ledger observations and obtain suitable technical/legal review.','Consider issuance only after the required approvals and operating arrangements exist.'],terms:{Oracle:'A mechanism that relays data or attestations to another system.',Custody:'Holding or controlling an asset under an agreed arrangement.',Tokenization:'Representing defined rights or records digitally; it does not itself create the underlying rights.'},sources:[['SEC investor education: crypto assets','https://www.investor.gov/crypto-assets']],type:'digital'}
};
const choiceCopy={plain:{heading:'Start with what you know.',sub:'Choose a guide. You can switch explanations at any time.'},professional:{heading:'Choose the instrument or workflow.',sub:'Source-linked orientation, evidence requirements and counterparty routing.'}};
function setExperience(value){experience=value==='professional'?'professional':'plain';try{localStorage.setItem('am-experience',experience);}catch{}$('#experience').value=experience;if(location.hash.startsWith('#learn'))showLearning(location.hash.split('/')[1]||'');else if(current&&!location.hash.startsWith('#knowledge')){if(hasUnsaved()){toast('Language preference saved. Your current legal edits remain on screen.');return;}renderCase();}}
$('#experience').value=experience;$('#experience').onchange=e=>setExperience(e.target.value);
async function showKnowledge(hash){$('#landing').hidden=true;$('#workspace').hidden=true;$('#learning').hidden=false;$('#learning').classList.add('kb-view');$('#footer').hidden=false;$('.topbar nav').hidden=false;$('#assistant').hidden=true;$('#assistant-toggle').hidden=true;const root=$('#learning-content');if(window.AssetKnowledge){await window.AssetKnowledge.show(root,hash,{base:BASE,download});}else{root.innerHTML='<div class="knowledge-shell"><h2>The knowledge library could not open.</h2><p>Please reload this page and try again.</p><a class="button outline" href="#learn">Open introductory guides ↗</a></div>';}}
function showLearning(slug){$('#landing').hidden=true;$('#workspace').hidden=true;$('#learning').hidden=false;$('#footer').hidden=false;$('.topbar nav').hidden=false;$('#assistant').hidden=true;$('#assistant-toggle').hidden=true;
 const root=$('#learning-content'),g=guides[slug],deepTopic={bonds:'bonds',sblc:'sblc',inherited:'inheritance',physical:'gold',unknown:'proof',desks:'proof',digital:'tokenization'}[slug]||'proof';
 if(!g){root.innerHTML=`<p class="eyebrow">THE ASSET MACHINE STARTER LIBRARY</p><h2>${choiceCopy[experience].heading}</h2><p class="muted">${choiceCopy[experience].sub}</p><div class="kb-guide-callout"><div><span class="tiny">GO DEEPER</span><p>Explore the full knowledge base, evidence checklists and primary sources.</p></div><a class="button outline" href="#knowledge">Open the knowledge base ↗</a></div><label for="guide-search">Find an explanation</label><input id="guide-search" class="search guide-search" type="search" placeholder="Try SBLC, inherited bond, gold, diamonds or trade desk"><div class="choice-grid" id="guide-list"></div><p class="fine" style="margin-top:24px">Seven introductory guides. Broader country coverage and the organization directory are being developed. These guides do not inspect or authenticate an asset.</p>`;
 const draw=query=>{const matches=Object.entries(guides).filter(([id,x])=>[id,x.name,x.question,x.plain,x.professional].join(' ').toLowerCase().includes(query.toLowerCase()));$('#guide-list').innerHTML=matches.length?matches.map(([id,x])=>`<a class="choice-card" href="#learn/${id}"><span>EXPLAIN MY ASSET</span><h3>${esc(x.name)}</h3><p>${esc(x.question)}</p></a>`).join(''):'<p class="notice">No matching starter guide yet. Try a broader term or choose “Unfamiliar names.”</p>';};draw('');$('#guide-search').oninput=e=>draw(e.target.value);return;}
 root.innerHTML=`<a class="crumb" href="#learn">← All guides</a><div class="guide-body"><div class="guide-art ${slug==='physical'?'photo-metals':slug==='desks'?'photo-desk':'photo-documents'}" role="img" aria-label="Illustrative asset editorial photograph"></div><p class="eyebrow">EXPLAIN MY ASSET / ${experience==='plain'?'PLAIN LANGUAGE':'PROFESSIONAL'}</p><h2 data-help-subject="${slug==='desks'?'professional':slug==='unknown'?'unknown-asset':deepTopic}">${esc(g.question)}</h2><div class="guide-tools"><a class="button outline mini" href="#knowledge/topic/${deepTopic}">Read the in-depth reference ↗</a><button class="outline mini" id="share-guide">Share this explanation ↗</button><button class="outline mini" id="guide-card">Download explanation card ↓</button><button class="outline mini" id="save-guide">Save guide text ↓</button></div><div class="panel"><p class="eyebrow">WHAT THIS COULD BE</p><p>${esc(g[experience])}</p></div><div class="panel"><p class="eyebrow">WHAT NEEDS CHECKING</p><ul>${g.checks.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div class="panel"><p class="eyebrow">YOUR NEXT MOVE</p><ol>${g.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><button class="primary" id="guide-project">Start a private project ↗</button><p class="fine">Creates an evidence workspace. It does not initiate a transaction or request bank records.</p></div><h3>Terms you may see</h3>${Object.entries(g.terms).map(([term,def])=>`<details ${experience==='plain'?'open':''}><summary>${esc(term)}</summary><p>${esc(def)}</p></details>`).join('')}<h3>Sources and scope</h3><ul class="source-list">${g.sources.map(([name,url])=>`<li><a href="${esc(safeHref(url))}" target="_blank" rel="noopener noreferrer">${esc(name)} ↗</a></li>`).join('')}</ul><p class="fine">Prepared November 3, 2026. Introductory education; source coverage and institutional requirements vary. No asset has been inspected, verified or valued by reading this guide.</p>${slug==='desks'?'<div class="notice"><strong>Organization directory: research in progress.</strong><p>Full institutional profiles and contacts are not available in this release. No directory subscription is being charged. You can prepare a project and record sourced contacts in its Next conversations section.</p></div>':''}<div class="notice">Sharing this explanation shares educational content only. Your documents, project details and attorney work are not included.</div></div>`;
 $('#guide-project').onclick=()=>{if(!user){login();return;}newCase(g.type);$('#goal').value='Help me understand '+g.name.toLowerCase()+' and identify the next evidence or professional review needed.';};
 $('#save-guide').onclick=()=>download('asset-machine-'+slug+'-guide.txt',guideText(slug));
 $('#guide-card').onclick=()=>download('asset-machine-'+slug+'-explanation.svg',guideCard(slug),'image/svg+xml');
 $('#share-guide').onclick=async()=>{const url='https://assetmachine.live/#learn/'+slug;const data={title:'Asset Machine: '+g.question,text:'An introductory explanation and evidence checklist. No private asset information is included.',url};try{if(navigator.share)await navigator.share(data);else if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(url);toast('Educational guide link copied. No private project details included.');}else{modal(`<h2>Share the explanation.</h2><label for="share-url">Educational link only</label><input id="share-url" readonly value="${esc(url)}">`);$('#share-url').select();}}catch(e){if(e.name!=='AbortError')toast('Sharing is unavailable. Download the explanation card or guide text instead.');}};
}
function guideText(slug){const g=guides[slug];return 'ASSET MACHINE — EDUCATIONAL GUIDE\n'+g.question+'\n\n'+g[experience]+'\n\nWHAT NEEDS CHECKING\n'+g.checks.map(x=>'• '+x).join('\n')+'\n\nYOUR NEXT MOVE\n'+g.steps.map((x,i)=>(i+1)+'. '+x).join('\n')+'\n\nSOURCES\n'+g.sources.map(([n,u])=>n+': '+u).join('\n')+'\n\nPrepared November 3, 2026. Education only; not an asset authentication or valuation.\nhttps://assetmachine.live/#learn/'+slug;}
function wrapCard(text,width=63){const words=text.split(/\s+/),lines=[];let line='';for(const word of words){if(line.length+word.length+1>width){lines.push(line);line=word;}else line+=(line?' ':'')+word;}if(line)lines.push(line);return lines;}
function guideCard(slug){const g=guides[slug],title=wrapCard(g.question,42),body=wrapCard(g[experience],88);return `<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="800" viewBox="0 0 1200 800"><defs><linearGradient id="bg" x2="1" y2="1"><stop stop-color="#20292d"/><stop offset="1" stop-color="#080b0d"/></linearGradient></defs><rect width="1200" height="800" fill="url(#bg)"/><rect x="35" y="35" width="1130" height="730" rx="8" fill="none" stroke="#b89566"/><text x="75" y="105" fill="#d6b57f" font-family="sans-serif" font-size="21" letter-spacing="5">ASSET MACHINE / EXPLAIN MY ASSET</text>${title.map((x,i)=>`<text x="75" y="${185+i*57}" fill="#f1eadb" font-family="Georgia,serif" font-size="46">${esc(x)}</text>`).join('')}${body.slice(0,7).map((x,i)=>`<text x="75" y="${350+i*32}" fill="#c6cecf" font-family="sans-serif" font-size="23">${esc(x)}</text>`).join('')}<text x="75" y="650" fill="#d6b57f" font-family="sans-serif" font-size="23">Understand it. Check the evidence. Choose your next move.</text><text x="75" y="700" fill="#f1eadb" font-family="sans-serif" font-size="21">assetmachine.live/#learn/${esc(slug)}</text><text x="75" y="737" fill="#a4adb0" font-family="sans-serif" font-size="16">Education only · November 3, 2026 · No private documents or authentication claims included</text></svg>`;}
function nextStepPanel(){const d=current;let text,target,label;if(!d.evidence.length){text='Add the documents or photographs you have. You can correct the extracted text afterward.';target='evidence';label='Add my documents';}else if(!d.findings.length){text='Read the extracted details, then run screening to record observations and unanswered questions.';target='findings';label='See checks and questions';}else if(!d.reports.length){text='Review the findings and missing evidence. If you need legal analysis, submit the project for the attorney’s consideration.';target='legal';label='View professional review';}else{text='Read the released report and prepare the next conversation using its actual conclusions and limitations.';target='contacts';label='Prepare my next conversation';}return `<div class="panel next-step"><p class="eyebrow">YOUR NEXT STEP</p><h3>${esc(label)}</h3><p>${esc(text)}</p><div class="actions"><button class="primary mini" data-go="${target}">${esc(label)} ↗</button><button class="outline mini" id="action-report">Download project action summary ↓</button></div><p class="fine">Describe it → Add evidence → Check the facts → Choose the next step</p></div>`;}
function actionReport(){const d=current;return 'ASSET MACHINE — PROJECT ACTION SUMMARY\nGenerated '+new Date().toISOString()+'\n\nProject: '+d.case.title+'\nStatus: '+(labels[d.case.status]||d.case.status)+'\n\nOWNER-SUPPLIED DESCRIPTION\n'+d.case.description+'\n\nDOCUMENTS\n'+d.evidence.map(e=>e.name+' | SHA-256 '+e.sha256+' | '+e.extraction_status).join('\n')+'\n\nRECORDED OBSERVATIONS AND GAPS\n'+(d.findings.length?d.findings.map(f=>f.title+'\n'+f.body+'\nScope: '+f.scope+'\nSource: '+(f.source_url||'No external source recorded')+'\nRecorded: '+f.created_at).join('\n\n'):'No screening findings recorded.')+'\n\nNEXT STEPS\n'+(!d.evidence.length?'Add supporting originals and confirm the extracted text.':!d.findings.length?'Run available screening and review its limitations.':!d.reports.length?'Resolve the missing evidence; request independent professional review where needed.':'Read the separately released attorney report and follow its scoped next steps.')+'\n\nReleased legal reports: '+d.reports.length+'. Download them separately from Legal review.\nThis generated summary is not an attorney opinion, issuer authentication, valuation or funding commitment. Private attorney notes and drafts are excluded.';}

$('#chat-form').onsubmit=async e=>{e.preventDefault();const text=$('#chat-input').value.trim();if(!text||!current)return;try{const d=await work('Reading the project evidence and preparing a response…',()=>post(endpoint('chat'),{message:text,communication_level:experience}));current.messages.push({role:'user',body:text},{role:'assistant',body:d.reply,knowledge_sources:Array.isArray(d.knowledge_sources)?d.knowledge_sources:[]});$('#chat-input').value='';renderMessages();}catch{}};
$('#record').onclick=()=>recordInto($('#chat-input'));$('#close-assistant').onclick=()=>{if(media?.state==='recording')media.stop();$('#assistant').hidden=true;$('#assistant-toggle').hidden=!current;};$('#assistant-toggle').onclick=openAssistant;$('#close-modal').onclick=closeModal;$('#account').onclick=()=>user?location.hash='workspace':login();$('#start').onclick=()=>begin();$('#legal-start').onclick=()=>begin();$('#closing-start').onclick=()=>user?location.hash='workspace':login();document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>begin(b.dataset.type));document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>location.hash=b.dataset.view==='projects'?'workspace':b.dataset.view);$('#logout').onclick=async()=>{try{await post('/logout');user=null;location.hash='home';await initSession();showLanding();}catch(e){toast(e.message);}};window.addEventListener('hashchange',()=>route().catch(e=>toast(e.message)));window.addEventListener('beforeunload',e=>{if(hasUnsaved()){e.preventDefault();e.returnValue='';}});(async()=>{await initSession();await route();})().catch(e=>toast(e.message));

const stages=[['01','EVIDENCE BEFORE ASSUMPTIONS','Know what you hold.','Collect original documents, confirm extracted details, and record screening concerns. Issuer confirmation, ownership and custody need independent evidence.','Evidence workspace available','Issuer authentication requires a source.'],['02','RIGHTS BEFORE ISSUANCE','Define what the asset represents.','Prepare a digital asset record linked to source evidence. Legal review must establish the rights, restrictions, custody and issuance terms before any token is created.','Preparation records available','Live token issuance is not connected.'],['03','CONTEXT BEFORE INTRODUCTIONS','Prepare the right conversation.','Record prospective buyers or lenders, their public sources, diligence questions and a factual briefing. Review every claim before sharing.','Contact briefings available','Seed LEAKER discovery and outreach are pending.'],['04','AGREEMENT BEFORE TRANSFER','Make the closing explicit.','A buyer or lender supplies the funds. Signed terms, custody, escrow and legally effective rights transfer must be coordinated by the responsible parties.','Settlement provider required','No funds are moved by this workspace.'],['05','SCOPE BEFORE SIGNAL','Keep the evidence current.','Review source dates and record changes to the evidence. External custody, reserve and valuation feeds require approved providers and clearly defined monitoring rules.','External feeds awaiting connection','An oracle feed is not bond authentication.']];
for(const b of document.querySelectorAll('[data-stage]'))b.onclick=()=>{document.querySelectorAll('[data-stage]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));const d=stages[Number(b.dataset.stage)];document.querySelector('#stage-detail').dataset.helpStage=['verify','structure','connect','settle','monitor'][Number(b.dataset.stage)];document.querySelector('#stage-detail').innerHTML=`<span class="stage-num">${d[0]}</span><div><p class="eyebrow">${d[1]}</p><h3>${d[2]}</h3><p>${d[3]}</p></div><div class="stage-status"><span class="signal"></span>${d[4]}<br><small>${d[5]}</small></div>`;};
document.querySelector('#oracle-start').onclick=()=>begin('digital');


// Native two-axis exploration: no wheel interception or forced vertical-to-horizontal scrolling.
const shelf=$('#asset-shelf'),motionPreference=window.matchMedia('(prefers-reduced-motion: reduce)');
function moveShelf(direction){if(!shelf)return;shelf.scrollBy({left:direction*(shelf.querySelector('.cinema-card')?.getBoundingClientRect().width+24||700),behavior:motionPreference.matches?'auto':'smooth'});}
$('#shelf-prev').onclick=()=>moveShelf(-1);$('#shelf-next').onclick=()=>moveShelf(1);
shelf.addEventListener('keydown',e=>{if(e.target!==shelf)return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();moveShelf(e.key==='ArrowRight'?1:-1);}});
let motionFrame=0;function updateReadingProgress(){motionFrame=0;const total=document.documentElement.scrollHeight-innerHeight;$('#reading-progress').style.width=(total>0?Math.min(100,Math.max(0,scrollY/total*100)):0)+'%';}
window.addEventListener('scroll',()=>{if(!motionFrame)motionFrame=requestAnimationFrame(updateReadingProgress);},{passive:true});window.addEventListener('resize',updateReadingProgress);window.addEventListener('hashchange',()=>requestAnimationFrame(updateReadingProgress));
if('IntersectionObserver' in window&&!motionPreference.matches){const reveal=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){e.target.classList.add('is-visible');reveal.unobserve(e.target);}},{threshold:.08});document.querySelectorAll('#start-here .choice-card,.cinema-heading,.machine-process .section-title,.legal-section').forEach(el=>{el.classList.add('reveal-ready');reveal.observe(el);});motionPreference.addEventListener('change',e=>{if(e.matches){document.querySelectorAll('.reveal-ready').forEach(el=>el.classList.add('is-visible'));reveal.disconnect();}});}

function updateShelfControls(){if(!shelf)return;$('#shelf-prev').disabled=shelf.scrollLeft<=2;$('#shelf-next').disabled=shelf.scrollLeft>=shelf.scrollWidth-shelf.clientWidth-2;}shelf.addEventListener('scroll',updateShelfControls,{passive:true});window.addEventListener('resize',updateShelfControls);window.addEventListener('hashchange',()=>requestAnimationFrame(updateShelfControls));requestAnimationFrame(updateShelfControls);

